DROP TABLE IF EXISTS `phpbb_forums`;
CREATE TABLE `phpbb_forums` (
  `forum_id` smallint(5) unsigned NOT NULL default '0',
  `cat_id` mediumint(8) unsigned NOT NULL default '0',
  `forum_name` varchar(150) default NULL,
  `forum_desc` text,
  `forum_status` tinyint(4) NOT NULL default '0',
  `forum_order` mediumint(8) unsigned NOT NULL default '1',
  `forum_posts` mediumint(8) unsigned NOT NULL default '0',
  `forum_topics` mediumint(8) unsigned NOT NULL default '0',
  `forum_last_post_id` mediumint(8) unsigned NOT NULL default '0',
  `prune_next` int(11) default NULL,
  `prune_enable` tinyint(1) NOT NULL default '0',
  `auth_view` tinyint(2) NOT NULL default '0',
  `auth_read` tinyint(2) NOT NULL default '0',
  `auth_post` tinyint(2) NOT NULL default '0',
  `auth_reply` tinyint(2) NOT NULL default '0',
  `auth_edit` tinyint(2) NOT NULL default '0',
  `auth_delete` tinyint(2) NOT NULL default '0',
  `auth_sticky` tinyint(2) NOT NULL default '0',
  `auth_announce` tinyint(2) NOT NULL default '0',
  `auth_vote` tinyint(2) NOT NULL default '0',
  `auth_pollcreate` tinyint(2) NOT NULL default '0',
  `auth_attachments` tinyint(2) NOT NULL default '0',
  PRIMARY KEY  (`forum_id`),
  KEY `forums_order` (`forum_order`),
  KEY `cat_id` (`cat_id`),
  KEY `forum_last_post_id` (`forum_last_post_id`)
) TYPE=MyISAM;
INSERT INTO `phpbb_forums` (`forum_id`,`cat_id`,`forum_name`,`forum_desc`,`forum_status`,`forum_order`,`forum_posts`,`forum_topics`,`forum_last_post_id`,`prune_next`,`prune_enable`,`auth_view`,`auth_read`,`auth_post`,`auth_reply`,`auth_edit`,`auth_delete`,`auth_sticky`,`auth_announce`,`auth_vote`,`auth_pollcreate`,`auth_attachments`) VALUES (27,11,'Contest / Polls / Surveys','Enter our uniquely entertaining contests for your chance to win select prizes all while having fun, or take a poll or survey as well as see what other pimps are saying.',0,30,3728,64,91121,NULL,0,0,0,1,1,1,3,3,3,1,1,0),(6,3,'Tracks','Images of tracks, arenas, and racing surfaces for RCs. Got a track to show off? Do it here.',0,30,1039,86,91065,1044458959,0,0,0,1,1,1,3,3,3,1,1,0),(8,4,'Swap-Meet','Straight outta LoCash, if you\'re new to the scene, make your trades, buys, and deals here (up to $20) - AT YOUR OWN RISK. This forum is used for members with no bitPimps cred yet. Topics not replied to within 60 days are auto-deleted.',0,10,60,7,90536,1142370740,1,0,0,1,1,1,3,3,3,1,1,0),(9,4,'Fo\' Sale','All stuff for sale that\'s off the fer schizzle hizzle, dizzle. You must have a minimum of 50 posts to post an item for sale. NO COMPANIES ALLOWED PLEASE. Topics not replied to within 60 days are auto-deleted.',0,20,122,16,91221,1143416087,1,0,0,1,1,1,3,3,3,1,1,0);
